package pl.mpospieszynski.site.shared.storage;

import java.util.Optional;
import java.util.regex.Pattern;
import org.springframework.http.MediaType;

/**
 * Where image files live: Supabase Storage in production, a local folder in the `dev` profile.
 * Writes forward the admin's own JWT (Supabase checks it with the bucket policy), so no service-role key exists.
 */
public interface MediaStorage {

    /** Keys are generated by the upload service: letters, digits, dot, dash and underscore only. */
    Pattern KEY = Pattern.compile("[A-Za-z0-9][A-Za-z0-9._-]{0,199}");

    void put(String key, byte[] content, MediaType contentType, String adminJwt);

    Optional<StoredObject> get(String key);

    void delete(String key, String adminJwt);

    static String requireValidKey(String key) {
        if (key == null || !KEY.matcher(key).matches() || key.contains("..")) {
            throw new IllegalArgumentException("Invalid media key: " + key);
        }
        return key;
    }

    record StoredObject(byte[] content, MediaType contentType) {
    }
}
